async updateTaskProgress(body: any): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/task/updateTaskProgress`, body)
      );

      if (res && res[0]?.msg == 1) {
        return true;
      }

      return false;
    } catch (err) {
      this.tost.error(`Task Progrss Update failed ${err}`);
      return false;
    }
  }

